#
# struct relocate_header is in relocate.h
#

.set noreorder
.globl	relocate_got_asm

# void relocate_got(int argc, char *argv[], unsigned long new_start_addr, unsigned long data)
# a0 = argc
# a1 = argv
# a2 = new_start_addr
# a3 = data
relocate_got_asm:
    lw t0, (1*4)(a2) # _start
    sub t6, a2, t0 # relocation offset

    #
    # Now we want to update GOT.
    #
    # GOT[0] is reserved.
    # GOT[1] is also reserved for the dynamic object
    # generated by GNU ld. Skip these reserved entries from relocation.
    #
    lw t3, (6*4)(a2) # num_got_entries
    lw t4, (7*4)(a2) # _GLOBAL_OFFSET_TABLE_
    add t4, t6     # relocate it
    addi t4, t4, 8 # 跳过开始的两个got
    li t2, 2
1:
    lw t1, 0(t4)
    beqz t1, 2f
    add t1, t6 # relocate it
    sw t1, 0(t4)
2:
    addi t2, 1
    blt t2, t3, 1b
    addi t4, 4

    #
    # Now we want to update dynamic relcoations
    #

    lw t1, (3*4)(a2) # __rel_dyn_start
    lw t2, (4*4)(a2) # __rel_dyn_end

    add t1, t6 # relocate it
    add t2, t6 # relocate it

    b 2f
    addi t1, 8 # 跳过第一个保留的位置

1:
    lw t3, -4(t1)
    sub t3, 3
    bnez t3, 2f # 跳过 非 R_MIPS_REL32 的位置
    nop

    lw t3, -8(t1)
    add t3, t6 # relocate it

    lw t4, 0(t3)
    add t4, t6 # relocate it

    sw t4, 0(t3)
2:
    blt t1, t2, 1b
    addi t1, 8

    lw t9, (10*4)(a2)
    jr t9
    nop

.end	relocate_got_asm